//===- mac_mode.cc ----------------------------------------------*- C++ -*-===//
//
// probe capture kernel for MAC config mode (0, 1, 4) `conv_32x8`
// (GENERATED by tools/gen_mac_modes.py). Per tile and signedness flavour (ss, su, us,
// uu; first letter is A) it runs mul_conv_32x8.
// Chunk layout: 2 operand blocks of T tiles (A, B).
//
//===----------------------------------------------------------------------===//

#include <stdint.h>

#include <aie_api/aie.hpp>

#define T 32
#define OUT_WORDS_PER_TILE 128

#define STORE(r, dst) \
  do { aie::accum<acc32, 32> w(r); aie::store_v((dst), w.to_vector<int32>(0)); } while (0)

extern "C" {

void mac_mode(uint8_t *restrict in, int32_t *restrict out) {
  uint8_t *in0 = in + 0;
  uint8_t *in1 = in + 0 + T * 64;
  event0();
  for (int n = 0; n < T; n++) {
    int32_t *o = out + n * OUT_WORDS_PER_TILE;
    { // ss
      v64int8 v0 = *(v64int8 *)(in0 + n * 64);
      v64int8 v1 = *(v64int8 *)(in1 + n * 64);
      v32acc32 r0 = mul_conv_32x8(v0, v1);
      STORE(r0, o + 0);
    }
    { // su
      v64int8 v0 = *(v64int8 *)(in0 + n * 64);
      v64uint8 v1 = *(v64uint8 *)(in1 + n * 64);
      v32acc32 r0 = mul_conv_32x8(v0, v1);
      STORE(r0, o + 32);
    }
    { // us
      v64uint8 v0 = *(v64uint8 *)(in0 + n * 64);
      v64int8 v1 = *(v64int8 *)(in1 + n * 64);
      v32acc32 r0 = mul_conv_32x8(v0, v1);
      STORE(r0, o + 64);
    }
    { // uu
      v64uint8 v0 = *(v64uint8 *)(in0 + n * 64);
      v64uint8 v1 = *(v64uint8 *)(in1 + n * 64);
      v32acc32 r0 = mul_conv_32x8(v0, v1);
      STORE(r0, o + 96);
    }
  }
  event1();
}

} // extern "C"
